<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import type {FormInstance} from 'ant-design-vue';
import {submitForm,api,matches,pagination,roleLabel,strongPasswordRule,useActions,type Row,type CurrentUser} from './api';import AppIcon from './AppIcon.vue';import PagePanel from './PagePanel.vue';
defineProps<{user:CurrentUser}>();const rows=ref<Row[]>([]),loading=ref(false),error=ref(''),search=ref(''),role=ref('all'),createOpen=ref(false),rolesOpen=ref(false),formRef=ref<FormInstance>(),resetRef=ref<FormInstance>(),resetTarget=ref<Row|null>(null),resetForm=ref({temporaryPassword:''});const fresh=()=>({username:'',displayName:'',roleCode:'READER',temporaryPassword:''}),form=ref(fresh());const {busy,perform}=useActions();
const filtered=computed(()=>rows.value.filter(row=>matches(row,search.value,['username','displayName'])&&(role.value==='all'||row.roleCode===role.value)));
async function refresh(){loading.value=true;error.value='';try{rows.value=await api('/api/users')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function openCreate(){form.value=fresh();createOpen.value=true}
async function create(){if(await perform('/api/users',form.value,'POST','用户已创建')){createOpen.value=false;form.value=fresh();await refresh()}}
function openReset(row:Row){resetTarget.value=row;resetForm.value={temporaryPassword:''}}
async function reset(){if(resetTarget.value&&await perform('/api/users/'+resetTarget.value.id+'/reset-password',resetForm.value,'POST','密码已重置，用户下次登录需修改')){resetTarget.value=null;resetForm.value.temporaryPassword='';await refresh()}}
async function toggle(row:Row){if(await perform('/api/users/'+row.id+(row.enabled?'/disable':'/enable'),{},'POST',row.enabled?'用户已停用':'用户已启用'))await refresh()}
watch(createOpen,open=>{if(!open){form.value.temporaryPassword='';formRef.value?.clearValidate()}});watch(resetTarget,value=>{if(!value){resetForm.value.temporaryPassword='';resetRef.value?.clearValidate()}});onMounted(refresh);defineExpose({refresh});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"/><div class="dg-summary"><div><span>内部用户</span><strong>{{rows.length}}</strong></div><div><span>已启用</span><strong>{{rows.filter(r=>r.enabled).length}}</strong></div><div><span>审批人员</span><strong>{{rows.filter(r=>r.enabled&&['ADMIN','APPROVER'].includes(r.roleCode)).length}}</strong></div><div><span>首次登录待改密</span><strong>{{rows.filter(r=>r.mustChangePassword).length}}</strong></div></div>
 <PagePanel title="内部用户"><template #actions><a-button @click="rolesOpen=true">角色权限</a-button><a-button type="primary" @click="openCreate"><AppIcon name="plus"/>新增用户</a-button></template><template #filters><a-input v-model:value="search" allow-clear placeholder="搜索姓名或账号" class="dg-search" aria-label="搜索用户"><template #prefix><AppIcon name="search"/></template></a-input><a-select v-model:value="role" class="dg-select" aria-label="角色" :options="[{value:'all',label:'全部角色'},...['ADMIN','APPROVER','READER'].map(value=>({value,label:roleLabel(value)}))]"/></template><a-table :data-source="filtered" :loading="loading" :pagination="pagination" row-key="id" :scroll="{x:800}"><a-table-column title="用户" :width="220"><template #default="{record}"><div class="dg-name-cell"><span class="dg-user-avatar">{{String(record.displayName||record.username).slice(0,1)}}</span><div><strong>{{record.displayName}}</strong><small>{{record.username}}</small></div></div></template></a-table-column><a-table-column title="角色"><template #default="{record}">{{roleLabel(record.roleCode)}}</template></a-table-column><a-table-column title="状态"><template #default="{record}"><span class="dg-status" :class="record.enabled?'good':'off'">{{record.enabled?'已启用':'已停用'}}</span></template></a-table-column><a-table-column title="密码状态"><template #default="{record}"><span :class="record.mustChangePassword?'dg-warn-text':'dg-muted'">{{record.mustChangePassword?'首次登录需修改':'已设置'}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="210"><template #default="{record}"><div class="dg-row-actions"><a-button type="link" :disabled="record.username===user.username" @click="openReset(record)">重置密码</a-button><a-popconfirm v-if="record.enabled" title="停用后将拒绝该用户的业务访问，确认停用？" ok-text="停用" cancel-text="取消" :disabled="record.username==='admin'||record.username===user.username" @confirm="toggle(record)"><a-button type="link" class="dg-muted-action" :disabled="record.username==='admin'||record.username===user.username||busy">停用</a-button></a-popconfirm><a-button v-else type="link" :disabled="busy" @click="toggle(record)">启用</a-button></div></template></a-table-column></a-table></PagePanel>
 <a-modal v-model:open="createOpen" title="新增内部用户" centered :width="600" ok-text="创建" cancel-text="取消" :confirm-loading="busy" @ok="submitForm(formRef,create)"><a-form ref="formRef" :model="form" layout="vertical" @finish="create"><div class="dg-form-grid"><a-form-item label="姓名" name="displayName" :rules="[{required:true,whitespace:true,message:'请输入姓名'},{max:100,message:'姓名过长'}]"><a-input v-model:value="form.displayName"/></a-form-item><a-form-item label="账号" name="username" :rules="[{required:true,message:'请输入账号'},{pattern:/^[A-Za-z0-9_.-]{3,64}$/,message:'账号为 3 到 64 位字母、数字、下划线、点或短横线'}]"><a-input v-model:value="form.username" autocomplete="off"/></a-form-item><a-form-item label="角色" name="roleCode"><a-select v-model:value="form.roleCode" :options="['READER','APPROVER','ADMIN'].map(value=>({value,label:roleLabel(value)}))"/></a-form-item><a-form-item label="临时密码" name="temporaryPassword" :rules="[strongPasswordRule]"><a-input-password v-model:value="form.temporaryPassword" autocomplete="new-password"/></a-form-item></div></a-form></a-modal>
 <a-modal :open="!!resetTarget" :title="'重置 '+(resetTarget?.displayName||'用户')+' 的密码'" centered ok-text="重置并要求修改" cancel-text="取消" :confirm-loading="busy" @ok="submitForm(resetRef,reset)" @cancel="resetTarget=null"><a-form ref="resetRef" :model="resetForm" layout="vertical" @finish="reset"><a-form-item label="临时密码" name="temporaryPassword" :rules="[strongPasswordRule]"><a-input-password v-model:value="resetForm.temporaryPassword" autocomplete="new-password"/></a-form-item></a-form></a-modal>
 <a-modal v-model:open="rolesOpen" title="角色权限" centered :width="600" :footer="null"><table class="dg-role-table"><thead><tr><th>角色</th><th>数据读取</th><th>审批处理</th><th>平台管理</th></tr></thead><tbody><tr><td>管理员</td><td>按授权</td><td>本人待办</td><td>允许</td></tr><tr><td>审批人员</td><td>按授权</td><td>本人待办</td><td>无权限</td></tr><tr><td>读取人员</td><td>按授权</td><td>无权限</td><td>无权限</td></tr></tbody></table><div class="dg-modal-footer"><a-button @click="rolesOpen=false">关闭</a-button></div></a-modal>
</template>
